<?php
declare(strict_types=1);
namespace App\Extensions\TitanMapsIntelligence\Tools;
use App\Extensions\TitanMapsIntelligence\Contracts\AuthorisedCompanyContext; use App\Extensions\TitanMapsIntelligence\Contracts\PermissionAuthorizer; use App\Extensions\TitanMapsIntelligence\Exceptions\MapsIntelligenceException; use App\Extensions\TitanMapsIntelligence\Services\ProviderQuotaGuard; use App\Extensions\TitanMapsIntelligence\Services\GovernedSpatialCapabilityExecutor;
final class OverrideProviderQuotaTool { public function __construct(private readonly AuthorisedCompanyContext $context,private readonly PermissionAuthorizer $auth,private readonly ProviderQuotaGuard $quota,private readonly GovernedSpatialCapabilityExecutor $governance){} public function execute(array $input):array{if(($input['confirmed']??false)!==true)throw MapsIntelligenceException::fromCode('MAPS_CONFIRMATION_REQUIRED','Provider quota override requires explicit confirmation.');$this->auth->authorize($this->context->userId(),$this->context->companyId(),'titan-maps-intelligence.provider-quota.override');$input['execution_origin']='ai';return $this->governance->execute('maps.provider.quota.override',$input,function()use($input){$p=$this->quota->override((string)$input['provider'],(int)($input['minutes']??60),(string)($input['reason']??'Emergency operational override'));return ['provider'=>$p->provider,'override_until'=>$p->override_until?->toAtomString(),'reason'=>$p->override_reason];});}}
